cd /tmp && cat > StackAllocNint.cs << 'EOF'
using System;

class Program
{
    static void Main()
    {
        Span<nint> nativeInts = stackalloc nint[5];
        for (int i = 0; i < nativeInts.Length; i++)
            nativeInts[i] = i * 10;

        for (int i = 0; i < nativeInts.Length; i++)
            Console.WriteLine($"nativeInts[{i}] = {nativeInts[i]}");

        Span<nuint> nativeUInts = stackalloc nuint[3];
        for (int i = 0; i < nativeUInts.Length; i++)
            nativeUInts[i] = (nuint)(i + 100);

        for (int i = 0; i < nativeUInts.Length; i++)
            Console.WriteLine($"nativeUInts[{i}] = {nativeUInts[i]}");

        Console.WriteLine($"sizeof(nint) = {sizeof(nint)}");
    }
}
EOF
